from pathlib import Path

profiles = {
'中康科技 - 公开报告与数据摘要': {'path':'05-行业机构/中康科技/中康科技-公开报告与数据摘要.md','promise':'中康科技公开报告和数据能为医药零售判断提供哪些事实底座','core':'中康科技资料最适合用于判断药品全终端、实体药店和健康商品的结构变化，但只能作为行业口径，不能替代平台、药店或药企的经营披露','terms':[('中康科技','医药健康产业数据与咨询服务机构，公开内容常涉及药品终端、实体药店、消费者洞察和行业会议。'),('公开报告与数据摘要','重点是还原报告口径、指标和可引用事实，而不是把报告改写成平台机会判断。'),('药品全终端/实体药店/健康商品','分别对应行业大盘、院外供给基本盘和药店增量品类。')],'facts':[('中康科技公开报告/会议资料','可提供药品终端、药店经营和健康消费趋势线索','不能证明单平台GMV或单店利润'),('2024年全终端约2.03万亿元、同比0.9%','说明行业规模仍大但增长偏弱','不能证明所有渠道同步增长'),('2025年全终端预计约19,742亿元、同比下降2.9%','提示行业进入高位调整和结构再分配','预测口径需要后续正式数据验证')],'mechanisms':[('中康数据为什么先看口径','中康资料往往按全终端、实体药店、健康商品或消费者洞察组织，口径不同，能支持的结论不同。','全终端规模能说明大盘，不能直接说明O2O订单；实体药店药品占比能说明药店基本盘，不能证明非药品类已经替代药品。'),('为什么总量放缓会放大渠道竞争','当全终端弱增长或下滑时，平台、药店、B2C、DTP争夺的是存量需求和结构变化。','药店仍要靠药品基本盘，但平台可能通过急用药和附近库存切入同一用户需求。'),('为什么机构资料要和财报交叉','机构资料讲行业结构，财报讲公司经营，两者解决不同问题。','中康数据提示行业承压后，还要看益丰、大参林、老百姓等公告里的毛利、现金流和门店效率。')],'classes':[('全终端数据','判断药品大盘和增速','规模、同比、终端拆分','不能直接用于平台份额'),('实体药店数据','判断院外供给和品类结构','药品占比、健康商品、客流','不能证明单店盈利'),('消费者洞察','判断需求场景','症状触发、家庭常备、复购','需要交易数据验证')],'indicators':[('报告名称、发布时间、统计口径','确认引用范围'),('全终端规模和增速','判断行业大盘变化'),('实体药店药品占比','判断药店基本盘'),('与上市公司公告交叉','验证行业趋势是否落到经营结果')]},
'本周行业变化': {'path':'05-行业机构/本周行业变化.md','promise':'2026-06-10至2026-06-16这一周有哪些真正新增的医药零售变化','core':'本周行业变化应区分新增事实、延续趋势和待验证事项；如果没有新增来源，就不能把年度趋势包装成周度结论','terms':[('本周','本文采用2026-06-10至2026-06-16，关注短周期新增信息。'),('行业变化','包括报告发布、政策动作、平台入口、公司公告和可验证数据变化。'),('新增事实/延续趋势/待验证','新增是本周新出现；延续是旧趋势继续成立；待验证是还缺少硬披露。')],'facts':[('本周资料更新','可整理总量、渠道、监管和企业效率线索','不能替代原文核验'),('行业机构资料','可确认全终端高位调整和渠道分流仍是背景','不能证明本周订单变化'),('监管资料','可确认网络售药、医保、处方和平台责任仍是约束','不能证明业务增长')],'mechanisms':[('为什么周度文章不能写成年度综述','周度文章的价值是识别本周新增变量，而不是重复“总量放缓、渠道分流”。','如果本周只有资料更新，文章应写“本周没有足够新事件，主要是旧趋势再确认”。'),('为什么要拆新增和延续','新增事实改变判断，延续趋势提供背景，二者混写会让读者误以为旧趋势刚发生。','全终端高位调整是延续趋势；某平台本周调整买药入口才是新增事件。'),('为什么待验证很重要','医药即时零售缺少公开订单、毛利、复购和退单数据，周度判断容易过度外推。','平台活动增多只能说明动作发生，不能说明留存改善。')],'classes':[('新增事实','本周新出现的信息','日期、来源、直接事实','必须有原始来源'),('延续趋势','过去已存在、本周继续成立','总量、渠道、监管','不能写成新结论'),('待验证事项','缺少硬数据的推论','订单、毛利、复购、履约','下周继续跟踪')],'indicators':[('本周新增来源数量','判断文章是否有周度价值'),('新增/延续/待验证拆分','避免泛化'),('高证据等级来源','提高可信度'),('下周待补资料','形成持续跟踪闭环')]},
'行业最新权威资讯': {'path':'05-行业机构/行业最新权威资讯.md','promise':'哪些最新公开资料可以作为医药零售研判的权威依据','core':'权威资讯的价值在可追溯和可证明，政府文件、公司公告、机构报告分别回答规则、公司和行业口径，不能混用','terms':[('权威资讯','优先指政府官网、上市公司公告、行业机构原文和正式报告。'),('最新','不是搜索结果最新，而是对判断产生新增信息。'),('可证明事项','每条资料必须说明能证明什么、不能证明什么。')],'facts':[('政府官网','证明规则要求、责任主体、监管流程','不能证明市场规模'),('上市公司公告','证明公司披露的收入、利润、门店、现金流','不能代表全行业'),('行业机构原文','证明特定统计口径下的市场趋势','不能替代财报或政策')],'mechanisms':[('为什么权威来源也要分层','政府、公司和机构资料的证据能力不同。','药监文件能证明处方审核要求，不能证明平台订单增长。'),('为什么“最新”要看增量','新发布不等于有新信息，二手转述旧报告不应提高权重。','同一数据被多篇媒体转述，只算一个原始事实。'),('为什么权威资讯需要引用边界','权威资料如果被用错，也会产生错误结论。','公司公告披露O2O收入，仍不等于能拆出某个平台贡献。')],'classes':[('监管文件','规则判断','主体责任、处方、医保、配送','不推市场规模'),('公司公告','企业判断','收入、利润、门店、现金流','不推全行业'),('机构报告','行业判断','规模、终端、品类','不推单平台')],'indicators':[('原文链接和发布主体','判断证据等级'),('发布时间和是否新增','判断资讯价值'),('可证明事项','控制引用边界'),('是否可交叉验证','提高结论稳健性')]},
'CCFA医药零售与连锁经营趋势摘要': {'path':'05-行业机构/补充资料/CCFA医药零售与连锁经营趋势摘要.md','promise':'CCFA连锁经营视角能解释医药零售哪些经营变化','core':'CCFA资料更适合解释连锁药店从扩店转向效率、组织和供应链竞争，但不能替代药品终端销售或单家公司财报','terms':[('CCFA','中国连锁经营协会相关公开资料，关注连锁零售、门店经营、供应链和组织能力。'),('医药零售','院外药品、健康商品和药事服务的零售体系。'),('连锁经营趋势','重点看标准化、区域密度、会员运营、数字化和供应链效率。')],'facts':[('CCFA公开资料','可观察连锁经营和消费趋势','不能证明药品终端规模'),('上市药店公告','可验证门店、收入、利润、现金流','不能代表所有药店'),('行业机构药店数据','可补充品类和终端结构','不能替代企业经营披露')],'mechanisms':[('为什么连锁率不是唯一指标','连锁率提高说明组织化提升，但不代表单店效率提升。','连锁药店扩店后，如果坪效和现金流下降，规模优势可能没有转化成经营质量。'),('为什么O2O要回到门店能力','医药O2O最终由门店库存、药师和履约承接。','同样上线平台，区域密度高的连锁更容易做附近履约。'),('为什么会员和供应链重要','药店增长从自然客流转向复购和效率后，会员识别和供应链周转变成核心。','慢病用户复购提醒比一次性活动更能体现连锁经营能力。')],'classes':[('规模经营','看覆盖能力','门店数、区域密度、连锁率','不代表盈利'),('效率经营','看经营质量','坪效、人效、费用率、现金流','需要财报验证'),('数字化经营','看承接能力','会员、O2O、库存准确率','不能只看上线')],'indicators':[('门店数和区域密度','判断供给覆盖'),('店均产出/坪效/人效','判断效率'),('会员复购和慢病服务','判断用户粘性'),('O2O毛利和履约成本','判断线上是否有效')]},
'O2O与B2C医药电商模式对比': {'path':'05-行业机构/补充资料/O2O与B2C医药电商模式对比.md','promise':'O2O和B2C在医药电商中分别解决什么问题','core':'O2O承接急用、附近库存和即时履约，B2C承接标准化复购和价格透明；二者不是互相替代，而是不同需求场景的分工','terms':[('O2O','线上下单、附近药店或本地供给即时履约，核心是附近库存和时效。'),('B2C','平台或商家通过仓配向用户发货，核心是标准化、价格透明和复购。'),('医药电商','比普通电商多处方、药师、医保、质量追溯和配送质量约束。')],'facts':[('即时零售报告','证明近场履约和本地供给价值','不能证明医药O2O盈利'),('平台公开资料','证明入口、履约承诺或合作动作','不能证明真实毛利和复购'),('药品网络销售监管','证明处方、审方、平台责任要求','不能证明渠道规模')],'mechanisms':[('为什么O2O适合急用药','急用药的核心是时间和附近库存，用户愿意为即时可得付出更高搜索和配送成本。','夜间发热、腹泻、过敏等场景更依赖附近药店库存。'),('为什么B2C适合复购和标准品','B2C依赖仓配和价格透明，更适合非急用、可计划、可囤货商品。','维生素、家用检测、部分慢病复购更容易走B2C。'),('为什么处方药让两种模式都复杂','处方药销售需要处方来源、审方、药师和配送质量，不能只比较流量和时效。','同一降压药复购可能走B2C，但首次诊疗和处方仍需要医疗链路。')],'classes':[('O2O','急用、附近库存、夜间需求','配送时效、库存准确、药师咨询','履约成本高'),('B2C','标准化复购、价格比较','仓配能力、价格、复购','急用体验弱'),('DTP/处方链路','特药和高专业度处方','处方、冷链、患者服务','不能按普通电商看')],'indicators':[('履约时效和库存准确率','验证O2O体验'),('价格和复购率','验证B2C价值'),('处方审核和药师服务','验证医药合规'),('退单率和毛利率','判断模式质量')]},
'中康科技药品全终端市场回顾与展望': {'path':'05-行业机构/补充资料/中康科技药品全终端市场回顾与展望.md','promise':'中康科技口径下药品全终端市场过去发生了什么、未来可能怎么变','core':'回顾数据说明行业大盘弱增长，展望数据提示高位调整；关键不是数字本身，而是终端和渠道结构如何变化','terms':[('中康科技','医药健康产业数据与咨询机构。'),('药品全终端','覆盖医院、基层、零售等药品终端的综合口径。'),('回顾与展望','回顾看已发生数据，展望看预测和趋势，两者证据等级不同。')],'facts':[('2024年全终端约2.03万亿元、同比0.9%','说明行业大盘弱增长','不能证明每个终端都增长'),('2025年预计约19,742亿元、同比下降2.9%','提示行业高位调整','预测需要验证'),('实体药店药品占比仍高','说明药品仍是药店基本盘','不能证明非药无机会')],'mechanisms':[('为什么回顾和展望要分开','回顾通常是已披露数据，展望是预测或机构判断，证据等级不同。','2024规模可作为历史事实，2025预计要等待后续验证。'),('为什么全终端下滑不等于需求消失','价格治理、终端转移、品类结构和支付变化都可能影响规模。','医院端下降可能伴随院外复购或基层承接变化。'),('为什么要关注终端结构','药企、药店和平台面对的是不同终端需求，而不是一个总盘子。','特药看院内+DTP，OTC看药店+O2O，健康商品看B2C和会员。')],'classes':[('医院终端','诊疗和处方形成','规模、品类、专科药','不代表院外复购'),('零售药店','院外购药和慢病复购','药品占比、门店效率','不代表平台表现'),('线上/电商','标准复购和即时需求','B2C、O2O、DTP','需拆场景')],'indicators':[('历史规模和预计规模','区分事实与预测'),('终端结构变化','判断需求转移'),('品类结构','判断药企机会'),('后续正式数据','验证展望是否兑现')]},
'全终端药品市场渠道对比_医院基层零售电商': {'path':'05-行业机构/补充资料/全终端药品市场渠道对比_医院基层零售电商.md','promise':'医院、基层、零售和电商分别承接哪些药品需求','core':'渠道对比的重点不是线上替代线下，而是不同渠道承接不同诊疗、复购、急用和专业服务场景','terms':[('全终端药品市场','把医院、基层、零售、电商、DTP等终端放在同一框架中观察。'),('医院/基层/零售/电商','分别对应诊疗处方、基层慢病、院外购药和线上复购/急用。'),('渠道对比','比较需求场景、服务能力和合规要求。')],'facts':[('米内网/中康等终端资料','可观察药品在不同终端的结构','不能证明单渠道利润'),('网络售药监管','证明线上渠道需要资质和处方流程','不能证明线上规模'),('上市药店公告','证明药店经营结果','不能代表医院或电商')],'mechanisms':[('为什么医院仍是处方形成中心','创新药、专科药和复杂疾病通常依赖医生诊断和院内治疗路径。','肿瘤药先在院内形成诊断和治疗方案，院外更多承接续方和服务。'),('为什么基层和药店承接慢病复购','基层和药店更接近患者日常生活，适合长期管理和复购。','高血压、糖尿病等慢病需要持续用药和监测。'),('为什么电商要拆B2C/O2O/DTP','线上渠道不是一个渠道，B2C看复购，O2O看急用，DTP看专业处方和患者服务。','同样是线上买药，退烧药和抗肿瘤药完全不同。')],'classes':[('医院','诊断和处方形成','专科、创新药、住院/门诊','不代表复购便利'),('基层/药店','慢病和常见病院外承接','医保、药师、门店密度','专业服务有限'),('电商/O2O/DTP','线上触达和履约','时效、复购、处方、冷链','需分模式')],'indicators':[('各终端规模和增速','判断需求分布'),('处方和医保链路','判断院外承接'),('线上模式拆分','避免混淆B2C/O2O/DTP'),('患者服务能力','判断专业药品承接')]},
'医药零售学习地图_入门到进阶': {'path':'05-行业机构/补充资料/医药零售学习地图_入门到进阶.md','promise':'读者应该按什么路径系统理解医药零售','core':'学习医药零售必须从概念和来源口径开始，再进入渠道、政策、财报、平台和医学基础；不能从平台动作直接推行业结论','terms':[('学习地图','把复杂资料拆成学习顺序。'),('入门','先掌握药品、药店、平台、医保、处方、药师和终端口径。'),('进阶','能够判断来源质量、事实边界、业务机制和指标验证。')],'facts':[('行业机构资料','提供规模、终端和渠道底座','不能替代公司和政策'),('政策监管资料','提供业务规则和责任主体','不能证明市场规模'),('财报和公告','提供企业经营验证','不能直接推行业整体')],'mechanisms':[('为什么先学口径','医药零售数据口径多，如果先看结论容易混淆全终端、零售、电商和O2O。','米内网三大终端和中康全终端不是同一个口径。'),('为什么再学业务流程','药品零售不是普通零售，处方、审方、医保、药师和质量追溯都会改变商业逻辑。','同样是下单，感冒药和处方降糖药流程不同。'),('为什么最后看平台和公司','平台动作和公司经营是结果层，需要用前面的行业、政策和医学基础解释。','入口增加不一定带来利润，门店增加不一定带来效率。')],'classes':[('基础层','概念和来源','终端、渠道、药品、医保','防止误读'),('机制层','业务流程','处方、履约、药师、支付','解释为什么'),('验证层','财报和指标','收入、毛利、复购、库存','判断是否成立')],'indicators':[('是否理解数据口径','避免错用资料'),('是否能解释业务流程','避免泛分析'),('是否能找到验证指标','形成研究闭环'),('是否区分事实和推论','提高专业性')]},
'医药零售行业关键事件时间线_2024-2026': {'path':'05-行业机构/补充资料/医药零售行业关键事件时间线_2024-2026.md','promise':'2024-2026年哪些事件真正改变了医药零售判断','core':'时间线不是新闻列表，而是把规模、渠道、监管、平台和公司事件按因果关系串起来','terms':[('关键事件时间线','按日期组织影响行业判断的事件。'),('2024-2026','区分历史事实、年度趋势和当期待验证变化。'),('关键事件','必须影响规模、渠道、监管、企业经营或用户场景。')],'facts':[('2024全终端弱增长','提供结构调整起点','不能证明所有渠道下滑'),('2025预计规模承压','提示高位调整延续','需要验证'),('监管与平台动作','说明业务约束和入口变化','不能直接证明经营结果')],'mechanisms':[('为什么时间线要看因果','事件相邻不等于因果，必须说明前后如何影响判断。','规模放缓可能促使药店重视效率，但不能证明某家药店利润下降。'),('为什么要按类型分事件','数据、政策、公司和平台事件影响层级不同。','政策影响流程，公司公告影响经营事实，平台动作影响入口和供给。'),('为什么2024-2026要分阶段','不同年份的主线不同，混在一起会失去判断。','2024看弱增长起点，2025看效率压力，2026看线上医保和平台承接是否兑现。')],'classes':[('数据事件','改变行业大盘判断','规模、增速、结构','证据较强'),('政策事件','改变业务流程','处方、医保、平台责任','影响边界'),('公司/平台事件','改变经营和入口线索','财报、合作、入口','需验证结果')],'indicators':[('事件日期和原始来源','保证时间线可信'),('事件类型','判断影响层级'),('前后关系','避免伪因果'),('后续验证节点','让时间线可更新')]},
'医药零售行业规模与渠道结构_2024-2026': {'path':'05-行业机构/补充资料/医药零售行业规模与渠道结构_2024-2026.md','promise':'2024-2026年医药零售规模和渠道结构如何变化','core':'规模告诉我们盘子是否扩张，渠道结构告诉我们需求由谁承接；行业机会更多来自结构再分配而不是单纯总量增长','terms':[('行业规模','市场总盘子和增速。'),('渠道结构','医院、基层、零售药店、B2C、O2O、DTP等承接关系。'),('2024-2026','需要区分历史数据、预计数据和待验证趋势。')],'facts':[('2024全终端约2.03万亿元、同比0.9%','显示弱增长','不能说明所有渠道相同'),('2025预计约19,742亿元、同比下降2.9%','显示承压','预测需验证'),('药店药品占比仍高','显示药店基本盘仍在药品','不能说明非药无机会')],'mechanisms':[('为什么总量不等于机会','总量承压时，机会可能来自渠道迁移、品类结构和服务效率。','院内处方外流、O2O急用药、DTP特药服务都不是简单总量增长。'),('为什么渠道结构比总量更可操作','企业和平台面对的是具体场景，不是抽象总盘子。','药企要判断产品适合院内、药店、DTP还是O2O。'),('为什么2024-2026要分事实和预测','时间越近，很多数据越可能是预计、阶段性披露或趋势判断。','2026平台机会需要订单和毛利验证，而不是仅靠2025行业数据。')],'classes':[('规模指标','判断大盘','全终端规模、同比','不拆渠道'),('渠道指标','判断需求流向','医院、基层、药店、电商','需口径一致'),('经营指标','验证承接质量','毛利、现金流、复购','需公司披露')],'indicators':[('全终端规模和同比','判断大盘'),('渠道占比和变化','判断需求迁移'),('药店药品/非药结构','判断基本盘'),('平台和药店披露','验证渠道结果')]},
'商务部研究院即时零售行业发展报告摘要': {'path':'05-行业机构/补充资料/商务部研究院即时零售行业发展报告摘要.md','promise':'商务部研究院即时零售报告能如何解释医药O2O','core':'商务部研究院资料能解释即时零售的本地供给和近场履约价值，但医药品类必须额外叠加资质、处方、药师、医保和质量责任','terms':[('商务部研究院','从商贸流通、消费和零售数字化角度研究即时零售。'),('即时零售','本地供给、线上下单、短时配送的零售模式。'),('医药即时零售','即时履约之外，还要处理药品监管和药事服务。')],'facts':[('即时零售报告','证明近场履约和本地零售数字化价值','不能直接证明医药品类利润'),('平台公开资料','证明入口和履约承诺','不能证明复购'),('药品监管文件','证明医药品类额外合规要求','不能证明市场规模')],'mechanisms':[('为什么即时零售适合医药部分场景','急用药和家庭常备补货对时间敏感，附近库存能提升可得性。','夜间腹泻、过敏、发热场景更需要近场履约。'),('为什么不能直接套普通即时零售','药品涉及适应症、处方、禁忌、药师解释和质量追溯。','同样30分钟送达，奶茶和处方药的责任完全不同。'),('为什么报告要和监管文件一起读','商务部研究院解释流通效率，药监/医保文件解释能不能做、怎么做。','平台买药必须同时满足交易、履约和药事服务。')],'classes':[('普通即时零售','本地供给和履约','时效、门店、配送','不含药事服务'),('医药O2O','急用药和附近库存','药师、处方、医保、质量','合规要求高'),('B2C医药','标准复购','价格、仓配、复购','急用弱')],'indicators':[('履约时效','验证即时价值'),('本地供给密度','验证可得性'),('药师和处方链路','验证医药适配'),('医药品类毛利和复购','验证商业质量')]},
'处方外流对零售药店和DTP药房的影响': {'path':'05-行业机构/补充资料/处方外流对零售药店和DTP药房的影响.md','promise':'处方外流如何改变零售药店和DTP药房的角色','core':'处方外流不是医院药品简单转移到药店，而是处方、支付、药师服务、冷链和患者管理能力的再分工','terms':[('处方外流','医院处方需求向院外药店、DTP、互联网医院或线上药房承接。'),('零售药店','承接常见病、慢病复购、医保购药和附近药师服务。'),('DTP药房','承接特药、高值药、冷链、患者随访和支付协同。')],'facts':[('医保/处方政策','证明院外购药和处方流转规则','不能证明药店利润增长'),('DTP公开资料','证明特药服务模式和患者管理需求','不能代表普通药店'),('上市药店公告','证明企业层面经营数据','不能直接拆出每类处方贡献')],'mechanisms':[('为什么处方外流先看处方来源','没有真实、合规、可审核的处方，院外承接无法成立。','慢病复购需要处方延续，特药需要专科诊断和治疗方案。'),('为什么DTP和普通药店不同','DTP面对高值、冷链、特殊支付和患者随访，服务成本和专业要求更高。','肿瘤靶向药不能按普通OTC销售流程理解。'),('为什么外流不必然提升利润','处方药可能毛利受限，服务、冷链、药师和患者管理都有成本。','订单增加但服务成本更高，利润未必改善。')],'classes':[('普通慢病处方','复购和依从性','续方、医保、药师提醒','需处方合规'),('DTP特药','专业服务','冷链、支付、随访','服务成本高'),('线上处方链路','互联网医院/平台','问诊、审方、配送','监管敏感')],'indicators':[('处方来源和审方流程','判断合规承接'),('DTP覆盖和冷链能力','判断特药服务'),('医保/商保支付','判断可负担性'),('患者留存和依从性','判断服务价值')]},
'实体药店行业变化_门店数连锁率单店产出': {'path':'05-行业机构/补充资料/实体药店行业变化_门店数连锁率单店产出.md','promise':'门店数、连锁率和单店产出如何共同反映实体药店变化','core':'实体药店不能只看扩店，门店数说明覆盖，连锁率说明组织化，单店产出才更接近经营效率','terms':[('门店数','药店供给网络规模。'),('连锁率','行业组织化和标准化程度。'),('单店产出','每家门店的收入或利润效率。')],'facts':[('上市药店公告','证明门店、收入、利润、现金流','不能代表所有药店'),('CCFA/行业机构资料','证明连锁经营趋势','不能证明单家公司质量'),('O2O公开资料','证明线上承接动作','不能证明门店利润改善')],'mechanisms':[('为什么门店数不是越多越好','扩店能提高覆盖，但也带来租金、人力、库存和管理成本。','如果新店爬坡慢，门店增长可能拖累利润。'),('为什么连锁率要结合效率看','连锁化提高采购和管理能力，但不自动提升单店产出。','标准化强的门店仍可能受客流下降影响。'),('为什么O2O会改变门店评价','门店既是线下零售点，也是线上履约节点，效率评价要加入库存和配送。','O2O订单多但平台费用高，可能不改善毛利。')],'classes':[('规模扩张','看供给覆盖','门店数、新开/关闭','不代表盈利'),('组织效率','看连锁能力','连锁率、供应链、标准化','需经营验证'),('单店质量','看经营结果','店均收入、坪效、人效、现金流','最接近质量')],'indicators':[('门店数和净增门店','判断扩张'),('关店率和新店爬坡','判断质量'),('店均收入/坪效/人效','判断效率'),('O2O毛利和费用','判断线上承接质量')]},
'米内网三大终端六大市场数据摘要': {'path':'05-行业机构/补充资料/米内网三大终端六大市场数据摘要.md','promise':'米内网三大终端六大市场口径能解释药品需求在哪些终端流动','core':'米内网数据适合做终端结构判断，尤其是医院、基层、实体药店和网上药店之间的分布，但不能直接证明单平台或单家药店经营表现','terms':[('米内网','医药行业数据和信息服务平台，常用于观察药品销售终端、医院用药、零售药店和药企市场表现。'),('三大终端','通常指公立医院终端、零售药店终端、公立基层医疗终端。'),('六大市场','进一步拆分城市公立医院、县级公立医院、城市社区、乡镇卫生院、实体药店、网上药店等市场。')],'facts':[('米内网终端数据','可判断药品销售在哪些终端发生','不能证明平台GMV'),('六大市场拆分','可观察院内、基层、实体药店和网上药店结构','不能替代公司财报'),('其他机构/公告','可交叉验证趋势','不同口径不能直接相加')],'mechanisms':[('为什么三大终端重要','三大终端把药品需求分成医院、零售和基层，先解决“药在哪里被销售”。','创新药更多看医院，OTC更多看零售，基层看慢病和基础用药。'),('为什么六大市场更有用','六大市场把医院和基层继续拆细，能看出城市、县域、社区、乡镇和线上之间的结构差异。','县级医院和城市医院变化，对药企渠道判断不同。'),('为什么不能直接推平台表现','米内网终端口径通常不是单平台经营口径，网上药店也不等于某个即时零售平台。','网上药店增长不能直接写成美团买药或京东买药增长。')],'classes':[('医院市场','诊疗和处方','城市/县级医院销售','不代表院外复购'),('基层市场','基层慢病和基础用药','社区/乡镇市场','受政策和支付影响'),('零售/网上药店','院外和线上承接','实体药店、网上药店','需拆平台和模式')],'indicators':[('三大终端占比','判断大类结构'),('六大市场增速','判断细分流向'),('品类/企业排名','判断药企机会'),('与财报和平台资料交叉','避免单口径误判')]},
'药品价格治理与零售药店利润结构变化': {'path':'05-行业机构/补充资料/药品价格治理与零售药店利润结构变化.md','promise':'药品价格治理如何影响零售药店利润结构','core':'价格治理会压缩简单价差和低价竞争空间，药店利润更依赖品类结构、费用控制、专业服务和运营效率','terms':[('药品价格治理','包括集采、挂网、比价、价格监测、医保控费等。'),('零售药店利润结构','包括毛利、费用、平台佣金、医保结算、库存和药师服务成本。'),('利润结构变化','从价差逻辑转向效率、服务和品类组合。')],'facts':[('医保/价格治理政策','证明价格规则和治理方向','不能证明单店利润'),('上市药店公告','证明毛利率、费用率、现金流','不能拆出每个政策影响'),('平台低价和补贴信息','证明竞争线索','不能证明可持续利润')],'mechanisms':[('为什么价格治理影响药店毛利','药品价格更透明后，传统价差空间可能缩小。','集采品种和比价工具会让用户更敏感。'),('为什么药店不能只靠低价','低价能带来客流，但药店还要承担租金、人力、药师和库存成本。','O2O低价订单如果平台费用高，可能拉低毛利。'),('为什么服务和品类更重要','当价差受压，药店需要靠慢病管理、专业咨询、健康商品和会员复购提升价值。','药师解释和会员复购能提高留存，但需要成本验证。')],'classes':[('政策价格压力','影响药品价差','集采、挂网、医保控费','不直接等于亏损'),('平台价格竞争','影响用户选择','补贴、券、配送费','可持续性待验证'),('药店经营结构','影响利润质量','毛利、费用、现金流','需财报验证')],'indicators':[('毛利率和费用率','判断利润压力'),('价格治理政策范围','判断影响品种'),('平台佣金和补贴','判断线上订单质量'),('品类结构和服务收入','判断转型能力')]},
'西普会 - 内容摘要': {'path':'05-行业机构/西普会/西普会-内容摘要.md','promise':'西普会公开内容能反映医药零售行业哪些共识和分歧','core':'西普会适合识别行业关注点和转型议题，但会议观点必须用机构数据、政策和公司公告验证，不能直接当经营结论','terms':[('西普会','医药健康产业会议和交流平台，常讨论药店转型、健康消费、数字化和产业趋势。'),('内容摘要','不是复述口号，而是提炼共识、分歧、事实和待验证问题。'),('会议观点','通常是趋势线索，证据等级低于监管文件和财报。')],'facts':[('会议主题和公开报道','可观察行业关注点','不能证明经营结果'),('中康/行业机构数据','可提供会议背景','不能代表企业落地'),('公司公告','可验证观点是否转化为经营结果','不能覆盖所有参会观点')],'mechanisms':[('为什么会议强调转型','当总量增长变弱、药店效率承压时，行业会议会集中讨论数字化、健康消费和专业服务。','会议热词背后通常是经营压力。'),('为什么会议内容不能直接用作结论','会议观点带有倡议和方向性，缺少完整经营数据。','“健康消费增长”要看药店非药收入和毛利，而不是只看发言。'),('为什么仍然值得跟踪','会议能提前暴露企业关注点和行业共识，适合形成后续验证清单。','如果多家企业讨论DTP或O2O，下一步要看财报和公告是否披露投入。')],'classes':[('行业共识','识别共同关注','主题、关键词、嘉宾观点','不是事实结果'),('经营信号','识别压力和机会','效率、品类、数字化','需数据验证'),('后续验证','落到公告和指标','收入、毛利、门店、O2O','防止口号化')],'indicators':[('会议主题关键词','判断行业关注点'),('是否有数据支撑','区分观点和事实'),('对应公司公告','验证落地'),('后续指标变化','判断转型效果')]},
'其他行业报告摘要_2025-2026': {'path':'06-其他行业报告/其他行业报告摘要_2025-2026.md','promise':'非核心医药报告能为医药零售提供哪些可迁移线索','core':'其他行业报告可以补充即时零售、本地生活、消费和物流视角，但医药结论必须回到药品终端、监管和企业资料验证','terms':[('其他行业报告','非核心医药机构但与即时零售、本地生活、消费、物流或数字化有关的报告。'),('可迁移线索','例如近场履约、即时需求、消费分层和本地供给。'),('不可直接迁移','处方药、医保、药师服务和药品质量责任不能从泛零售报告直接推出。')],'facts':[('即时零售/消费报告','可说明本地履约和用户需求变化','不能证明医药品类表现'),('医药行业机构资料','可验证药品终端和药店结构','不能解释所有消费行为'),('监管资料','可限定医药业务边界','不能证明商业机会')],'mechanisms':[('为什么跨行业报告有价值','医药即时零售也是本地零售的一部分，履约和用户即时需求可参考泛零售。','附近库存和短时配送逻辑对药品急用场景有启发。'),('为什么不能直接迁移','药品有处方、禁忌、药师和监管责任，不能按普通商品转化率理解。','外卖高频不代表处方药高频。'),('为什么需要医药资料校验','跨行业报告提供场景假设，医药资料验证是否能落地。','本地生活报告说即时需求增长，还要看药品O2O订单和合规链路。')],'classes':[('可迁移部分','履约和消费场景','时效、附近供给、用户即时性','只作为线索'),('需校验部分','医药专业约束','处方、医保、药师','必须用医药来源'),('不可迁移部分','普通商品转化结论','GMV、复购、毛利','不能直接套用')],'indicators':[('报告行业属性','判断能否迁移'),('医药验证来源','防止泛化'),('履约和用户指标','提取可用线索'),('合规和专业指标','判断医药适配')]},
'医药零售行业全景摘要_2025-2026': {'path':'06-其他行业报告/医药零售行业全景摘要_2025-2026.md','promise':'2025-2026年医药零售行业的规模、渠道、监管和经营主线是什么','core':'医药零售全景不是资料堆叠，而是说明行业从总量增长转向结构再分配，渠道、监管和效率共同决定机会','terms':[('全景摘要','把规模、渠道、品类、政策、企业经营和用户场景放在同一框架。'),('医药零售行业','包括实体药店、连锁药店、B2C、O2O、DTP、医保、处方和药事服务。'),('2025-2026','重点看总量承压、渠道分流、监管约束和效率竞争。')],'facts':[('全终端规模数据','说明行业大盘高位调整','不能证明具体渠道表现'),('实体药店药品占比','说明药店基本盘仍在药品','不能证明非药没有机会'),('监管和医保资料','说明线上买药和院外承接边界','不能证明市场规模')],'mechanisms':[('为什么全景要从总量开始','总量决定行业增长背景，弱增长意味着企业要从结构和效率找机会。','2025预计规模承压时，平台和药店争夺的是存量需求。'),('为什么渠道分工是核心','不同药品和用户需求由不同渠道承接。','OTC适合药店/O2O，慢病适合药店复购，特药适合DTP和患者服务。'),('为什么监管决定线上空间','医药线上化必须满足资质、处方、审方、医保和配送质量。','买药入口再强，如果处方和医保链路不稳，也难以规模化。')],'classes':[('行业大盘','规模和增速','全终端、同比','判断背景'),('渠道结构','需求承接','药店、B2C、O2O、DTP','判断机会'),('经营质量','企业结果','毛利、现金流、门店、复购','验证落地')],'indicators':[('全终端规模和增速','判断大盘'),('渠道和品类结构','判断分流'),('监管和医保进展','判断业务空间'),('上市公司经营指标','验证行业判断')]} }

def make(title,p):
    lines=[f'# {title}','','> - 引用级别：✅可供研判参考','> - 最后更新：2026-06-18','','## 一句话定位','',f'本文回答：{p["promise"]}。',f'核心判断是：{p["core"]}。','本文不能证明：单平台GMV、单门店利润、单品动销、用户复购或企业经营结果，除非原始报告、公司公告或监管文件直接披露。','','## 一、先讲清标题里的概念和关系','']
    for k,v in p['terms']:
        lines.append(f'- **{k}**：{v}')
    lines += ['', '这一组概念合在一起，实际讨论的是：标题中的机构、口径或渠道如何支撑一个有边界的行业判断，而不是把资料摘要直接改写成业务结论。', '', '## 二、事实底座：目前能确定什么', '', '| 事实/资料 | 能说明什么 | 不能说明什么 |', '|---|---|---|']
    for a,b,c in p['facts']:
        lines.append(f'| {a} | {b} | {c} |')
    lines += ['', '这组事实说明：行业报告首先提供的是方向、口径和结构线索。要形成专业判断，还必须解释这些事实通过什么业务机制影响平台、药店、药企或用户。', '', '## 三、业务机制拆解：为什么会这样', '']
    for i,(h,logic,example) in enumerate(p['mechanisms'],1):
        lines += [f'### {i}. {h}', '', f'- 发生逻辑：{logic}', f'- 具体例子：{example}', '- 对判断的影响：它决定本文应形成“有条件、可验证”的判断，而不是把行业事实直接外推成单一主体的经营结论。','']
    lines += ['## 四、分类讨论：不同对象不能混在一起看','', '| 类型 | 适合回答的问题 | 关键指标 | 风险/限制 |','|---|---|---|---|']
    for a,b,c,d in p['classes']:
        lines.append(f'| {a} | {b} | {c} | {d} |')
    lines += ['', '分类讨论的核心是：同一篇行业报告里可能同时出现规模、渠道、政策和企业经营线索，但这些线索的证据等级不同，必须分别使用。', '', '## 五、需要关注指标/为什么', '', '| 需要关注指标 | 为什么 |','|---|---|']
    for a,b in p['indicators']:
        lines.append(f'| {a} | {b} |')
    return '\n'.join(lines)+'\n'

for title,p in profiles.items():
    Path(p['path']).write_text(make(title,p), encoding='utf-8')
print('rewritten deep specific', len(profiles))
